import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { Button, FormControl, MenuItem, Select } from "@mui/material";
import { useTranslation } from "react-i18next";
import "../css/common.css";

export const RestartPageMidContent = () => {
  const location = useLocation();
  const { attempted, levelName, totalCount, type, levelToRestart } =
    location.state || {};
  const { t } = useTranslation();
  let navigate = useNavigate();
  let [level, setLevel] = useState(levelToRestart);

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  const handleRestart = () => {
    switch (levelToRestart) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-3 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                {levelName}
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                    fontSize: "calc(.6rem + .4vw)",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          <div className="row flex-grow-1" style={{ height: "85%" }}>
            <div
              className="col d-flex justify-content-center align-items-center"
              style={{ height: "100%" }}
            >
              <div className="restartDiv">
                <div>
                  {attempted === "NA" ? (
                    <div>
                      <span>Congratulations! </span>You have successfully
                      completed the {levelToRestart}.
                    </div>
                  ) : (
                    <div>
                      You have attempted {attempted} out of {totalCount} {type}.
                    </div>
                  )}
                </div>
                <div className="text-center mt-3">
                  <Button
                    variant="contained"
                    onClick={handleRestart}
                    sx={{
                      background: "#0F477E",
                      color: "#ffffff",
                      fontSize: "calc(.6rem + .4vw)",
                    }}
                  >
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              <ul>{t("instruction_restart")}</ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
