import React, { useState } from "react";
import data from "../listenAndIdentify.json";
import CircularProgress from "@material-ui/core/CircularProgress";
import ReactAudioPlayer from "react-audio-player";
import asset from "../asset/asset";
import { useNavigate } from "react-router-dom";
import { FormControl, MenuItem, Select, Slider } from "@mui/material";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import useWebSocket, { ReadyState } from "react-use-websocket";

const Level1MidContent = () => {
  const navigate = useNavigate();
  const [pageName, setpageName] = useState("Level 1");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [randomNumber, setRandomNumber] = useState(0);
  const [showMessage, setShowMessage] = useState(false);
  const parse = require("html-react-parser").default;
  const [randomNumberArray, setRandomNumberArray] = useState([0]);
  const [correct, setCorrect] = useState(false);
  const { t } = useTranslation();
  const [level, setLevel] = useState("Level 1");

  const handleNextButton = () => {
    // Remove border from all images first
    for (let i = 0; i < 3; i++) {
      const img = document.getElementById(`img-${i}`);
      if (img) img.style.border = "none";
    }

    setShowMessage(false);
    let randomNo = Math.floor(Math.random() * data.level1.length);
    if (randomNumberArray.length !== 10) {
      if (randomNumberArray.includes(randomNo)) {
        handleNextButton();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNo]);
        setRandomNumber(randomNo);
      }
    } else {
      navigate("/launchpage/englishactivity/level1/restart", {
        state: {
          attempted: "NA",
          levelName: "Identify the correct image",
          totalCount: 10,
          type: "sentences",
          levelToRestart: "Level 1",
        },
      });
    }
    ReactGA.event({
      action: `Eng32|Listen and identify|Clicked on NEXT image to get next audio`,
      category: `Eng32|NEXT image clicked`,
      label: `Eng32|Clicked on NEXT image`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "NEXT image",
      "Clicked",
      "Clicked to get the next audio",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleImageClick = (imageSrc, imageId) => {
    const correctImageSrc = data.level1[randomNumber].correctImage;

    // Remove border from all images first
    for (let i = 0; i < 3; i++) {
      const img = document.getElementById(`img-${i}`);
      if (img) img.style.border = "none";
    }

    const imgElement = document.getElementById(imageId);
    if (!imgElement) return;

    if (imageSrc === correctImageSrc) {
      imgElement.style.border = "4px solid green";
      setCorrect(true);
      setShowMessage(true);
      setTimeout(handleNextButton, 3000);
    } else {
      imgElement.style.border = "4px solid red";
      setCorrect(false);
      setShowMessage(true);
    }

    ReactGA.event({
      action: `Eng32|Listen and identify|Clicked on image in level 1`,
      category: `Eng32|image clicked`,
      label: `Eng32|Clicked on image`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "image clicked",
      "Clicked",
      "Clicked to check the result",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleLevelChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log(
          "Invalid input coming from level change dropdown in level 1"
        );
        break;
    }
    ReactGA.event({
      action: `Eng32|Listen and identify|Clicked on select level dropdown to change the level`,
      category: `Eng32|select level dropdown Dropdown clicked`,
      label: `Eng32|Clicked on select level dropdown`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "select level dropdown",
      "Clicked",
      "Clicked to navigate to level-1",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-5 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Identify the correct image
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  label="Select Adverb"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-3 mt-5">
            <div className="d-flex align-items-center">
              <span className="me-3">Audio</span>
              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={10}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{10}
              </span>
            </div>
          </div>
          <div className="row mb-3">
            <div className="d-flex align-items-center">
              {!data.level1[randomNumber].audioSrc ? (
                <CircularProgress />
              ) : (
                <>
                  <ReactAudioPlayer
                    style={{ width: "100%" }}
                    src={require(`../audio/${data.level1[randomNumber].audioSrc}`)}
                    controls
                  />
                </>
              )}

              <img
                style={{ width: "10%", cursor: "pointer" }}
                src={asset.next}
                alt="Click here"
                onClick={handleNextButton}
              />
            </div>
          </div>
          <div className="row justify-content-center text-center mb-5">
            {[
              data.level1[randomNumber].image1,
              data.level1[randomNumber].image2,
              data.level1[randomNumber].image3,
            ].map((imgSrc, index) => {
              const imageId = `img-${index}`;
              return (
                <div className="col-12 col-sm-4 mb-3" key={index}>
                  <img
                    id={imageId}
                    src={require(`../image/ActivityImages/${imgSrc}`)}
                    alt={`image ${index + 1}`}
                    className="img-fluid"
                    style={{
                      maxHeight: "200px",
                      objectFit: "contain",
                      borderRadius: "8px",
                      cursor: "pointer",
                    }}
                    onClick={() => handleImageClick(imgSrc, imageId)}
                  />
                </div>
              );
            })}
          </div>
          <div className="row justify-content-center">
            {showMessage && (
              <div
                className="d-flex justify-content-center align-items-center"
                style={{
                  width: "auto",
                  height: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px",
                  padding: "1rem",
                }}
              >
                <div>
                  {correct ? (
                    <div>
                      <span style={{ color: "#098B0D" }}>Great job!</span> You
                      have chosen the correct picture.
                    </div>
                  ) : (
                    <span>{parse(data.level1[randomNumber].IncorrectFB)}</span>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              <ul>
                <li>{t("instr1")}</li>
                <li>{t("instr2")}</li>
                <li>{t("instr3")}</li>
                <li>{t("instr4")}</li>
                <li>{t("instr5")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level1MidContent;
