import React, { useState } from "react";
import data from "../listenAndIdentify.json";
import asset from "../asset/asset";
import { useNavigate } from "react-router-dom";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import useWebSocket, { ReadyState } from "react-use-websocket";
import AudioPlayer from "./AudioPlayer.js";

const Level2MidContent = () => {
  const [pageName, setpageName] = useState("Level 2");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const navigate = useNavigate();
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  const { t } = useTranslation();
  const [level, setLevel] = useState("Level 2");
  let [isNextDisable, seIsNextDisable] = useState(true);
  let [skipCount, setSkipCount] = useState(0);

  const [feedback, setFeedback] = useState({
    firstAudioplayed: false,
    secondAudioPlayed: false,
    thirdAudioPlayed: false,
    fourthAudioPlayed: false,

    firstAnswerStatus: "",
    secondAnswerStatus: "",
    thirdAnswerStatus: "",
    fourthAnswerStatus: "", // "true" => right tick image, "false" => "wrong tick image" ""=>not clicked yet,
  });

  const handleNextButton = () => {
    let randomNo = Math.floor(Math.random() * data.level2.length);
    if (randomNumberArray.length !== 3) {
      if (randomNumberArray.includes(randomNo)) {
        handleNextButton();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNo]);
        setRandomNumber(randomNo);
      }
    } else {
      navigate("/launchpage/englishactivity/level2/restart", {
        state: {
          attempted: "NA",
          levelName: "Identify the correct object from a given image",
          totalCount: 3,
          type: "sentences",
          levelToRestart: "Level 2",
        },
      });
    }
  };

  const handleImageClick = (imageSrc, imageId) => {};

  const handleLevelChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Invalid input coming from level change dropdown!");
        break;
    }
    ReactGA.event({
      action: `Eng32|Listen and identify|Clicked on select level dropdown to change the level in level 2`,
      category: `Eng32|select level dropdown Dropdown clicked`,
      label: `Eng32|Clicked on select level dropdown`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "select level dropdown",
      "Clicked",
      "Clicked to switch the levels",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNextButton();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-5 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Identify the correct object from a given image
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  label="Select Adverb"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-3 mt-5">
            <div className="d-flex align-items-center">
              <span className="me-3">Audio</span>
              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={3}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{3}
              </span>
            </div>
          </div>

          <div className="row mb-5" style={{ height: "50%" }}>
            {/* Left Column */}
            <div
              className="col d-flex flex-column justify-content-center align-items-center"
              style={{ gap: "50px" }}
            >
              <div className="d-flex align-items-center">
                <AudioPlayer
                  src={require(`../audio/Level2/${data.level2[randomNumber].audioSrc1}`)}
                />
                {feedback.firstAudioplayed &&
                  feedback.firstAnswerStatus !== "" && (
                    <img
                      src={
                        feedback.firstAnswerStatus
                          ? asset.righttick
                          : asset.wrongTick
                      }
                      alt="Right tick image not found."
                      style={{
                        marginLeft: "10px",
                        width: "50px",
                        height: "50px",
                      }}
                    />
                  )}
              </div>
              <div className="d-flex align-items-center">
                <AudioPlayer
                  src={require(`../audio/Level2/${data.level2[randomNumber].audioSrc2}`)}
                />
                {feedback.secondAudioPlayed &&
                  feedback.secondAnswerStatus !== "" && (
                    <img
                      src={
                        feedback.firstAnswerStatus
                          ? asset.righttick
                          : asset.wrongTick
                      }
                      alt="Right tick image not found."
                      style={{
                        marginLeft: "10px",
                        width: "50px",
                        height: "50px",
                      }}
                    />
                  )}
              </div>
            </div>

            {/* Middle Column (Image) */}
            <div className="col d-flex justify-content-center align-items-center">
              <div
                style={{
                  boxShadow:
                    "rgba(6, 24, 44, 0.4) 0px 0px 0px 2px, rgba(6, 24, 44, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset",
                  padding: "10px",
                }}
              >
                <img
                  className="img-fluid"
                  src={require(`../image/ActivityImages/Level2/${data.level2[randomNumber].imageSrc}`)}
                  alt="Activity visual"
                />
              </div>
            </div>

            {/* Right Column */}
            <div
              className="col d-flex flex-column justify-content-center align-items-center"
              style={{ gap: "50px" }}
            >
              <div className="d-flex align-items-center">
                <AudioPlayer
                  src={require(`../audio/Level2/${data.level2[randomNumber].audioSrc3}`)}
                />
                {feedback.thirdAudioPlayed &&
                  feedback.thirdAnswerStatus !== "" && (
                    <img
                      src={
                        feedback.firstAnswerStatus
                          ? asset.righttick
                          : asset.wrongTick
                      }
                      alt="Right tick image not found."
                      style={{
                        marginLeft: "10px",
                        width: "50px",
                        height: "50px",
                      }}
                    />
                  )}
              </div>
              <div className="d-flex align-items-center">
                <AudioPlayer
                  src={require(`../audio/Level2/${data.level2[randomNumber].audioSrc4}`)}
                />
                {feedback.fourthAudioPlayed &&
                  feedback.fourthAnswerStatus !== "" && (
                    <img
                      src={
                        feedback.firstAnswerStatus
                          ? asset.righttick
                          : asset.wrongTick
                      }
                      alt="Right tick image not found."
                      style={{
                        marginLeft: "10px",
                        width: "50px",
                        height: "50px",
                      }}
                    />
                  )}
              </div>
            </div>
          </div>

          <div className="row mb-5">
            <div className="d-flex justify-content-around">
              <Button
                variant="contained"
                onClick={handleSkip}
                sx={{ background: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
              >
                {t("skip")}
              </Button>
              <Button
                disabled={isNextDisable}
                variant="contained"
                onClick={handleNextButton}
                sx={{ background: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
              >
                {randomNumberArray.length == 3 ? t("finish") : t("next")}
              </Button>
            </div>
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              <ul>
                <li>{t("instr1")}</li>
                <li>{t("instr2")}</li>
                <li>{t("instr3")}</li>
                <li>{t("instr4")}</li>
                <li>{t("instr5")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2MidContent;
